WITH base AS (SELECT *, discount * shipping_fee AS discount_times_shipping_fee FROM orders WHERE shipping_fee <= 27) SELECT id, customer_id, store_id, status, shipping_fee, discount_times_shipping_fee, LAST_VALUE(shipping_fee) IGNORE NULLS OVER (PARTITION BY MONTH(order_date) ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_shipping_fee, NTILE(4) OVER (PARTITION BY status ORDER BY amount DESC, id) AS amount_bucket, MAX(shipping_fee) OVER (PARTITION BY customer_id) AS customer_id_max_shipping_fee FROM base
